alter table public.profiles add column if not exists referral_code text;
alter table public.profiles add column if not exists referral_bonus_credits integer not null default 0;
create unique index if not exists profiles_referral_code_key on public.profiles(referral_code) where referral_code is not null;
update public.profiles set referral_code='HUSTLE-'||upper(substr(replace(id::text,'-',''),1,8)) where referral_code is null;

create table if not exists public.referrals (id uuid primary key default gen_random_uuid(),referrer_id uuid not null references auth.users(id) on delete cascade,referred_id uuid not null unique references auth.users(id) on delete cascade,referral_code text not null,status text not null default 'joined',rewarded_at timestamptz,created_at timestamptz not null default now(),check(referrer_id<>referred_id));
alter table public.referrals enable row level security;
drop policy if exists "Users can view their referrals" on public.referrals;
create policy "Users can view their referrals" on public.referrals for select to authenticated using(auth.uid()=referrer_id or auth.uid()=referred_id);

create table if not exists public.hustle_challenge_progress (user_id uuid primary key references auth.users(id) on delete cascade,completed_days integer[] not null default '{}',current_day integer not null default 1,started_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.hustle_challenge_progress enable row level security;
drop policy if exists "Users manage own challenge progress" on public.hustle_challenge_progress;
create policy "Users manage own challenge progress" on public.hustle_challenge_progress for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin insert into public.profiles(id,email,full_name,referral_code) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',''),'HUSTLE-'||upper(substr(replace(new.id::text,'-',''),1,8))) on conflict(id) do update set email=excluded.email,referral_code=coalesce(public.profiles.referral_code,excluded.referral_code); return new; end; $$;

create or replace function public.claim_referral(p_code text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_referrer uuid;v_referred uuid:=auth.uid();v_id uuid;begin if v_referred is null then return jsonb_build_object('ok',false,'error','Sign in required');end if;select id into v_referrer from public.profiles where upper(referral_code)=upper(trim(p_code)) limit 1;if v_referrer is null then return jsonb_build_object('ok',false,'error','Referral code not found');end if;if v_referrer=v_referred then return jsonb_build_object('ok',false,'error','You cannot use your own referral code');end if;insert into public.referrals(referrer_id,referred_id,referral_code,status) values(v_referrer,v_referred,upper(trim(p_code)),'joined') on conflict(referred_id) do nothing returning id into v_id;if v_id is null then return jsonb_build_object('ok',false,'error','Referral already claimed');end if;update public.profiles set referral_bonus_credits=coalesce(referral_bonus_credits,0)+5,updated_at=now() where id in(v_referrer,v_referred);update public.referrals set status='rewarded',rewarded_at=now() where id=v_id;return jsonb_build_object('ok',true,'bonus',5);end;$$;
revoke all on function public.claim_referral(text) from public;grant execute on function public.claim_referral(text) to authenticated;

create or replace function public.get_referral_stats() returns jsonb language sql security definer set search_path=public,pg_temp as $$ select jsonb_build_object('code',(select referral_code from public.profiles where id=auth.uid()),'referrals',(select count(*) from public.referrals where referrer_id=auth.uid()),'bonus',(select coalesce(referral_bonus_credits,0) from public.profiles where id=auth.uid())); $$;
revoke all on function public.get_referral_stats() from public;grant execute on function public.get_referral_stats() to authenticated;

create or replace function public.claim_challenge_day(p_day integer) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_days integer[];begin if auth.uid() is null then return jsonb_build_object('ok',false,'error','Sign in required');end if;if p_day<1 or p_day>7 then return jsonb_build_object('ok',false,'error','Invalid challenge day');end if;insert into public.hustle_challenge_progress(user_id) values(auth.uid()) on conflict(user_id) do nothing;select completed_days into v_days from public.hustle_challenge_progress where user_id=auth.uid();if p_day=any(v_days) then return jsonb_build_object('ok',true,'already',true,'completed_days',v_days);end if;if p_day>1 and not(p_day-1=any(v_days)) then return jsonb_build_object('ok',false,'error','Complete the previous day first');end if;v_days:=array_append(v_days,p_day);update public.hustle_challenge_progress set completed_days=v_days,current_day=least(7,p_day+1),updated_at=now() where user_id=auth.uid();return jsonb_build_object('ok',true,'completed_days',v_days,'current_day',least(7,p_day+1));end;$$;
revoke all on function public.claim_challenge_day(integer) from public;grant execute on function public.claim_challenge_day(integer) to authenticated;
